  /// Register an async implementation of grpcdc.kafka.v1.Kafka on a Server.
  static void RegisterKafkaServerAsync(grpcdc::Server& server,
                                      KafkaServerAsync& impl) {
    // Adapters are retained for the process lifetime: registration is
    // once-per-process and bounded by service count.
    static std::vector<std::shared_ptr<KafkaServerAsyncAdapter>> adapters;
    auto adapter = std::make_shared<KafkaServerAsyncAdapter>(&impl);
    adapters.push_back(adapter);
    RegisterKafkaServer(server, *adapter);
  }
